def test_exact32_no_extra_duplicate_foreign_or_late_admission(self):
    for seq in range(1,33):
        current=event(seq)
        self.gate.declare(current,self.deadline,self.abort)
        self.gate.mark_validated({'sequence':seq,'duration_ns':p.CADENCE_MIN})
    with self.assertRaises(p.ResearchError):self.gate.declare(event(33),self.deadline,self.abort)
    with self.assertRaises(p.ResearchError):self.gate.declare(event(1),self.deadline,self.abort)
    for current in (dict(event(1),stream_id=True),dict(event(1),source_process_id='foreign'),
            dict(event(1),admission_timestamp_ms=32500),dict(event(1),duration_ns=1)):
        with self.assertRaises(p.ResearchError):p.AdmissionGate(contract()).declare(current,self.deadline,self.abort)

test_run_ci_checks.RunCiChecksTests.test.method_source:
def test_failure_traceback_is_flushed_before_the_suite_returns(self):
    class Failing(unittest.TestCase):
        def runTest(self):
            self.fail("original immediate failure")

    class ObservedStream(io.StringIO):
        def __init__(self):
            super().__init__()
            self.flushed = []

        def flush(self):
            self.flushed.append(self.getvalue())

    stream = ObservedStream()
    result = ci.RecordedResult(unittest.runner._WritelnDecorator(stream), True, 2)
    Failing().run(result)
    self.assertTrue(any("original immediate failure" in text and "Traceback" in text
                        for text in stream.flushed))
    self.assertIn('"event": "test_started"', stream.getvalue())
    self.assertIn('"event": "test_terminal"', stream.getvalue())
    self.assertIn('"outcome": "failure"', stream.getvalue())
    self.assertEqual(len(result.failures), 1)

